def verify_jug_steps(steps, jugs=(8, 5), target=6):
    """Simulate a list of pour/fill/empty steps and check if
    either jug ends up holding exactly `target` liters."""
    state = {size: 0 for size in jugs}
    cap = dict(state)          # capacities
    record = [state.copy()]

    for step in steps:
        op, *args = step.split()

        if op == "fill":
            state[int(args[0])] = int(args[0])

        elif op == "empty":
            state[int(args[0])] = 0

        elif op == "pour":
            src, dst = int(args[0][0]), int(args[0][-1])
            amount = min(state[src], cap[dst] - state[dst])
            state[src] -= amount
            state[dst] += amount

        else:
            raise ValueError(f"Unknown step: {step}")

        record.append(state.copy())

    # print the trace so the user can see what happened
    for i, s in enumerate(record):
        print(f"Step {i}: {s}")

    # success if any jug holds exactly `target` liters
    return any(v == target for v in state.values())


# --- test with our Lisbon-rainy-day solution ---
steps = [
    "fill 8",
    "pour 8->5",
    "empty 5",
    "pour 8->5",
    "fill 8",
    "pour 8->5",
]

print("\nSuccess:", verify_jug_steps(steps))   # → True
